UPDATE capability_definitions
SET supported_verticals = (
  SELECT jsonb_agg(DISTINCT elem)
  FROM jsonb_array_elements_text(
    supported_verticals || '["GENERAL_COMMERCE","RETAIL_STORE","STATIONERY_BOOKSTORE","COSMETICS_RETAIL","BOUTIQUE","WHOLESALE","SUPERMARKET"]'::jsonb
  ) elem
),
updated_at = NOW()
WHERE NOT (supported_verticals @> '["*"]'::jsonb)
  AND code = ANY(ARRAY['GENERAL_COMMERCE','INVENTORY','SALES','PURCHASING','POS','CRM','LOYALTY','PROMOTIONS','BARCODE','PRICE_LISTS','MULTI_STORE','WAREHOUSE','CASH_SESSION','CASH_MOVEMENT','CASH_RECONCILIATION','B2B','CREDIT','BULK','CUSTOMER_CREDIT','CUSTOMER_MANAGEMENT','SUPPLIER_MANAGEMENT','RFQ','SUPPLIER_RETURNS','RETURNS_LOGISTICS','STORE_MANAGEMENT','MULTI_REGISTER','BOOKSTORE','BOOK_CATALOG','ISBN','STATIONERY','COSMETICS_RETAIL','COSMETIC_PRODUCT','LOT_TRACKING','EXPIRATION','FEFO','QUARANTINE','RECALL']::text[]);

