UPDATE business_profiles
SET default_policy_bundle = COALESCE(default_policy_bundle, '{}'::jsonb) || '{
  "store": {
    "returnPolicy": {"windowDays": 14},
    "discountPolicy": {"maxLineDiscountPct": 20},
    "pricingPolicy": {"priceLists": true},
    "paymentPolicy": {"methods": ["CASH","CARD","MOBILE_MONEY","BANK_TRANSFER"]},
    "creditPolicy": {"requireCustomerOnCreditSale": true},
    "openingPolicy": {"oneActiveSessionPerRegister": true},
    "closingPolicy": {"varianceApprovalRequired": true},
    "inventoryPolicy": {"salesMustNotPostLedgerDirectly": true}
  }
}'::jsonb,
updated_at = NOW()
WHERE code IN ('GENERAL_COMMERCE', 'RETAIL_STORE', 'STATIONERY_BOOKSTORE', 'COSMETICS_RETAIL');

